/* Token Radar — a dark scope theme: deep navy, radar green, one amber accent. */
:root {
  --bg: #070c11;
  --panel: #0d151d;
  --panel-2: #111c26;
  --line: #1d2c3a;
  --text: #dcebf3;
  --muted: #8299ab;
  --faint: #5a7185;
  --green: #2ee6a8;
  --green-dim: #14503a;
  --cyan: #45c8f0;
  --amber: #f5b83d;
  --red: #f06a6a;
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", Menlo, Consolas, monospace;
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}
* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background:
    radial-gradient(1100px 480px at 85% -120px, rgba(46, 230, 168, 0.07), transparent 60%),
    radial-gradient(900px 500px at -10% 0, rgba(69, 200, 240, 0.05), transparent 55%),
    var(--bg);
  color: var(--text);
  font-family: var(--sans);
  font-size: 15px;
  line-height: 1.5;
}
main { max-width: 1180px; margin: 0 auto; padding: 0 20px 48px; }

/* Masthead */
.masthead { border-bottom: 1px solid var(--line); background: rgba(13, 21, 29, 0.6); }
.masthead-inner {
  max-width: 1180px; margin: 0 auto; padding: 26px 20px 20px;
  display: flex; justify-content: space-between; align-items: flex-end; gap: 24px; flex-wrap: wrap;
}
.brand { display: flex; gap: 18px; align-items: center; }
.brand-mark { position: relative; width: 58px; height: 58px; flex: none; }
.brand-mark .ring {
  position: absolute; inset: 0; border: 1px solid var(--green-dim); border-radius: 50%;
}
.brand-mark .r2 { inset: 11px; }
.brand-mark .r3 { inset: 22px; }
.brand-mark .blip {
  position: absolute; left: 38px; top: 13px; width: 7px; height: 7px; border-radius: 50%;
  background: var(--green); box-shadow: 0 0 10px var(--green);
}
h1 { margin: 0; font-size: 30px; letter-spacing: 0.14em; font-weight: 800; }
.tagline { margin: 2px 0 0; color: var(--muted); font-size: 15px; }
.snapshot-line { margin: 0; color: var(--faint); font-family: var(--mono); font-size: 12.5px; text-align: right; }

/* Stat chips */
.stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(168px, 1fr)); gap: 12px; margin: 22px 0 6px; }
.stat { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 12px 14px; }
.stat .v { font-family: var(--mono); font-size: 21px; font-weight: 700; color: var(--green); }
.stat .k { color: var(--muted); font-size: 12.5px; margin-top: 2px; }

/* Method */
.method { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 18px 20px; margin: 16px 0 22px; }
.method h2 { margin: 0 0 6px; font-size: 17px; letter-spacing: 0.04em; }
.formula { font-family: var(--mono); font-size: 15.5px; color: var(--cyan); margin: 0 0 10px; }
.method-notes { margin: 0 0 12px; padding-left: 18px; color: var(--muted); font-size: 13.5px; }
.method-notes li { margin: 3px 0; }
.multiples h3 { margin: 0 0 8px; font-size: 13px; color: var(--muted); font-weight: 600; letter-spacing: 0.03em; }
.multiple-chips { display: flex; flex-wrap: wrap; gap: 7px; }
.mchip { font-family: var(--mono); font-size: 12px; border: 1px solid var(--line); border-radius: 999px; padding: 3px 10px; color: var(--text); background: var(--panel-2); }
.mchip b { color: var(--green); font-weight: 700; }

/* Controls */
.controls { display: flex; gap: 12px; align-items: flex-end; flex-wrap: wrap; margin-bottom: 12px; }
.control { display: flex; flex-direction: column; gap: 5px; font-size: 12.5px; color: var(--muted); }
.control.grow { flex: 1 1 220px; }
.control input[type="search"], .control select {
  background: var(--panel); border: 1px solid var(--line); color: var(--text);
  border-radius: 8px; padding: 8px 10px; font-size: 14px; font-family: var(--sans);
}
.control.check { flex-direction: row; align-items: center; gap: 7px; padding-bottom: 9px; font-size: 13.5px; color: var(--text); }
.control.check input { width: 16px; height: 16px; accent-color: var(--green); }
.count { margin: 0 0 9px auto; color: var(--faint); font-family: var(--mono); font-size: 12.5px; }

/* Table */
.table-wrap { border: 1px solid var(--line); border-radius: 10px; overflow: hidden; background: var(--panel); }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
thead th {
  text-align: left; font-size: 12px; letter-spacing: 0.06em; text-transform: uppercase; color: var(--muted);
  padding: 11px 12px; border-bottom: 1px solid var(--line); cursor: pointer; user-select: none; white-space: nowrap; background: var(--panel-2);
}
thead th.num, tbody td.num { text-align: right; }
thead th.sorted { color: var(--green); }
tbody td { padding: 9px 12px; border-bottom: 1px solid rgba(29, 44, 58, 0.55); vertical-align: middle; }
tbody tr { cursor: pointer; }
tbody tr:hover { background: rgba(46, 230, 168, 0.045); }
tbody tr:last-child td { border-bottom: none; }
td.rank { font-family: var(--mono); color: var(--faint); }
td .pname { font-weight: 650; }
td .pcat { display: block; color: var(--muted); font-size: 12px; }
.watch { color: var(--amber); font-size: 11px; border: 1px solid rgba(245, 184, 61, 0.4); border-radius: 999px; padding: 0 7px; margin-left: 7px; vertical-align: 2px; white-space: nowrap; }
td.num { font-family: var(--mono); font-size: 13.5px; white-space: nowrap; }
td.implied { color: var(--green); font-weight: 700; }
.pos { color: var(--green); }
.neg { color: var(--red); }
.hint { color: var(--faint); font-size: 12.5px; margin: 10px 2px 0; }

/* Detail view */
body.detail-mode .stats, body.detail-mode .method { display: none; }
.back {
  background: var(--panel); color: var(--text); border: 1px solid var(--line); border-radius: 8px;
  padding: 8px 14px; font-size: 14px; cursor: pointer; margin-bottom: 16px;
}
.back:hover { border-color: var(--green-dim); color: var(--green); }
.detail-head { display: flex; justify-content: space-between; gap: 20px; flex-wrap: wrap; align-items: flex-end; }
.detail-head h2 { margin: 0; font-size: 26px; }
.detail-head .sub { color: var(--muted); margin-top: 3px; }
.detail-implied { text-align: right; }
.detail-implied .v { font-family: var(--mono); font-size: 30px; font-weight: 800; color: var(--green); }
.detail-implied .k { color: var(--muted); font-size: 12.5px; }
.detail-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; margin: 18px 0; }
.detail-grid .stat .v { color: var(--text); font-size: 17px; }
.panel { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 18px 20px; margin: 16px 0; }
.panel h3 { margin: 0 0 12px; font-size: 15.5px; letter-spacing: 0.03em; }
.factor { display: grid; grid-template-columns: 210px 1fr 92px; gap: 12px; align-items: center; margin: 9px 0; font-size: 13.5px; }
.factor .fname { color: var(--muted); }
.factor .fbar { height: 9px; background: var(--panel-2); border-radius: 99px; overflow: hidden; }
.factor .fbar i { display: block; height: 100%; background: linear-gradient(90deg, var(--green-dim), var(--green)); }
.factor .fval { font-family: var(--mono); text-align: right; }
.factor.total { border-top: 1px solid var(--line); padding-top: 11px; margin-top: 13px; }
.factor.total .fname { color: var(--text); font-weight: 650; }
.factor.total .fval { color: var(--green); font-weight: 800; }
ol.steps { margin: 0; padding-left: 22px; }
ol.steps li { margin: 10px 0; }
ol.steps li::marker { color: var(--green); font-family: var(--mono); font-weight: 700; }

/* Footer */
footer { border-top: 1px solid var(--line); margin-top: 34px; padding-top: 16px; color: var(--faint); font-size: 12.5px; }
footer p { margin: 5px 0; }
